const data = $input.first().json;
  const items = [];
  const seenTickers = new Set();

  for (const asset of [...data.assets, ...data.watchlist]) {
    if (asset.name.toLowerCase().includes('etf')) continue;

    if (asset.ticker && seenTickers.has(asset.ticker)) continue;
    if (asset.ticker) seenTickers.add(asset.ticker);

    const isCrypto = asset.name.toLowerCase().includes('bitcoin')
      || asset.ticker === 'BTC-EUR';
    const isCommodity = asset.ticker === 'GC=F';

    const query = isCrypto
      ? `${asset.name} crypto news`
      : isCommodity
        ? 'Gold commodity price news'
        : `${asset.name} stock news`;

    items.push({ json: { name: asset.name, ticker: asset.ticker, query } });
  }

  items.push({ json: { name: 'Makro',  ticker: null, query: 'global stock market outlook' } });
  items.push({ json: { name: 'Zinsen', ticker: null, query: 'Federal Reserve ECB interest rates inflation' } });

  return items;

const results = $input.all().map(item => ({
   name:    item.json.name,
   ticker:  item.json.ticker,
   answer:  item.json.answer,
   results: item.json.results?.map(r => ({
     title:   r.title,
     url:     r.url,
     content: r.content
   }))
 }));

 return [{ json: { news: results } }];

const items = $input.all().map(i => {
    const { quantity_unit, ...rest } = i.json;
    return { ...rest, unit: quantity_unit };
  });

  return [{
    json: {
      assets:    items.filter(i => i.record_type === 'asset'),
      watchlist: items.filter(i => i.record_type === 'watchlist')
    }
  }];

const prices   = $('Fetch Prices').first().json;
  const allNews  = $('Aggregate News').first().json.news;
  const strategy = $('Extract from File').first().json.data;

  const knownNames = new Set([
    ...prices.assets.map(a => a.name),
    ...prices.watchlist.map(w => w.name),
  ]);

  const newsMap   = {};
  const macroNews = [];
  allNews.forEach(n => {
    const cleaned = { ...n, results: n.results?.map(({ content, ...rest }) => rest) ?? [] };
    if (knownNames.has(n.name)) newsMap[n.name] = cleaned;
    else macroNews.push(cleaned);
  });

  const pct = (x) => (x == null || isNaN(x)) ? null : Math.round(x * 10000) / 100;

  function calcAsset(a) {
    const qty   = parseFloat(a.quantity) || 0;
    const buyIn = parseFloat(a.buy_in);
    const currentValueEur = a.price != null ? a.price * qty : null;
    const performancePct  = (buyIn && a.price)
      ? Math.round((a.price / buyIn - 1) * 10000) / 100 : null;
    return {
      ...a,
      quantity:          qty,
      buy_in:            isNaN(buyIn) ? null : buyIn,
      current_value_eur: currentValueEur != null ? Math.round(currentValueEur * 100) / 100 : null,
      performance_pct:   performancePct,
      perf_1w_pct:       pct(a.perf_1w),
      cagr_3y_pct:       pct(a.cagr_3y),
      news:              newsMap[a.name] || null,
    };
  }

  const assetsCalc = prices.assets.map(calcAsset);
  const totalEur   = assetsCalc.reduce((s, a) => s + (a.current_value_eur || 0), 0);

  const assets = assetsCalc.map(a => ({
    ...a,
    weight_pct: (a.current_value_eur != null && totalEur > 0)
      ? Math.round(a.current_value_eur / totalEur * 10000) / 100 : null,
  }));

  // Basket-Aggregate, gewichtet nach current_value_eur
  const round2 = (x) => Math.round(x * 100) / 100;
  const basketMap = {};
  assets.forEach(a => {
    const b = a.basket || 'Sonstige';
    if (!basketMap[b]) basketMap[b] = { basket: b, weight_pct: 0, perfNum: 0, perfDen: 0, weekNum: 0, weekDen: 0 };
    const m = basketMap[b];
    const v = a.current_value_eur || 0;
    m.weight_pct += (a.weight_pct || 0);
    if (a.performance_pct != null) { m.perfNum += a.performance_pct * v; m.perfDen += v; }
    if (a.perf_1w_pct != null)     { m.weekNum += a.perf_1w_pct * v;     m.weekDen += v; }
  });
  const basket_summary = Object.values(basketMap).map(m => ({
    basket:       m.basket,
    weight_pct:   round2(m.weight_pct),
    avg_perf_pct: m.perfDen > 0 ? round2(m.perfNum / m.perfDen) : null,
    avg_week_pct: m.weekDen > 0 ? round2(m.weekNum / m.weekDen) : null,
  })).sort((x, y) => (y.weight_pct || 0) - (x.weight_pct || 0));

  const watchlist = prices.watchlist.map(w => ({
    ...w,
    perf_1w_pct: pct(w.perf_1w),
    cagr_3y_pct: pct(w.cagr_3y),
    news:        newsMap[w.name] || null,
  }));

  return [{ json: {
    assets,
    watchlist,
    basket_summary,
    macronews:           macroNews,
    strategy,
    portfolio_total_eur: Math.round(totalEur * 100) / 100,
  } }];

const data = $('Combine Data').first().json;
const llm  = $input.first().json;
// Text-Blöcke nach type filtern statt per Index: bei aktivem Extended Thinking
// steht auf content[0] ein thinking-Block, der Report erst auf content[1].
let md = (Array.isArray(llm.content) ? llm.content : [])
  .filter(c => c?.type === 'text' && typeof c.text === 'string')
  .map(c => c.text)
  .join('\n')
  || (typeof llm.text === 'string' ? llm.text : '');

// Kein stiller Fallback auf '': sonst blieben nur die Tabellen übrig und der
// Report sähe erfolgreich aus, obwohl der komplette Bericht fehlt.
if (!md.trim()) {
  throw new Error('Assembly: kein Text-Block von "Message Opus". Vorhandene Blocktypen: ['
    + (llm.content ?? []).map(c => c?.type).join(', ') + '] – Top-Level-Keys: ['
    + Object.keys(llm ?? {}).join(', ') + ']');
}

// dt. Zahlenformat (ICU-unabhängig, daher kein toLocaleString)
function deNum(x, dec = 2) {
  if (x == null || isNaN(x)) return 'n/a';
  const fixed = Number(x).toFixed(dec);
  let [int, frac] = fixed.split('.');
  const neg = int.startsWith('-'); if (neg) int = int.slice(1);
  int = int.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (neg ? '-' : '') + int + (frac ? ',' + frac : '');
}
const strip0 = (s) => s.includes(',') ? s.replace(/,?0+$/, '') : s;
const fmtNum = (x) => deNum(x, 2);
const fmtEur = (x) => (x == null || isNaN(x)) ? 'n/a' : deNum(x, 2) + ' €';
const fmtQty = (x) => (x == null || isNaN(x)) ? 'n/a' : strip0(deNum(x, 4));
const fmtPct = (x) => (x == null || isNaN(x)) ? 'n/a' : (x > 0 ? '+' : '') + deNum(x, 2) + ' %';
const fmtW   = (x) => (x == null || isNaN(x)) ? 'n/a' : deNum(x, 2) + ' %';
const tr     = (t) => t || 'n/a';

// Robuste Zeilen: jede Zelle wird von Umbrüchen befreit, Spalten mit ' | ' verbunden.
const mkRow = (cells) => '| ' + cells.map(c => String(c).replace(/\s*\n\s*/g, ' ')).join(' | ') + ' |';
const sep   = (n) => '|' + '---|'.repeat(n);

// Thesis-Verdikte aus <!--THESIS ...--> lesen und Block entfernen
const thesis = {};
const tm = md.match(/<!--\s*THESIS([\s\S]*?)-->/i);
if (tm) {
  tm[1].split('\n').forEach(line => {
    const idx = line.lastIndexOf(':');
    if (idx > -1) {
      const name = line.slice(0, idx).trim().replace(/^[-*]\s*/, '');
      const val  = line.slice(idx + 1).trim().toLowerCase();
      if (name) thesis[name] = val;
    }
  });
  md = md.replace(tm[0], '').trim();
}
const allowed = new Set(['intakt', 'angeschlagen', 'gebrochen']);
const thesisFor = (name) => allowed.has(thesis[name]) ? thesis[name] : '–';

const overview = [
  mkRow(['Basket', 'Gewicht', 'Ø Perf. seit Kauf', 'Wochenperf.']),
  sep(4),
  ...data.basket_summary.map(b => mkRow([
    b.basket, fmtW(b.weight_pct), fmtPct(b.avg_perf_pct), fmtPct(b.avg_week_pct),
  ])),
].join('\n');

const holdings = [
  mkRow(['Asset', 'Kurs (€)', 'Perf. seit Kauf', 'Woche', 'Anzahl', 'Gesamtwert', 'Gewicht', 'CAGR 3J', 'Sharpe',
'Trend', 'Thesis']),
  sep(11),
  ...data.assets.map(a => mkRow([
    a.name, fmtNum(a.price), fmtPct(a.performance_pct), fmtPct(a.perf_1w_pct),
    fmtQty(a.quantity), fmtEur(a.current_value_eur), fmtW(a.weight_pct),
    fmtPct(a.cagr_3y_pct), a.sharpe == null ? 'n/a' : fmtNum(a.sharpe),
    tr(a.trend), thesisFor(a.name),
  ])),
].join('\n');

const watch = [
  mkRow(['Asset', 'Kurs', 'Trend']),
  sep(3),
  ...data.watchlist.map(w => mkRow([w.name, fmtNum(w.price), tr(w.trend)])),
].join('\n');

md = md.split('[[GESAMTWERT]]').join(fmtEur(data.portfolio_total_eur));

const blocks = {
  '[[TABELLE:UEBERSICHT]]':  overview,
  '[[TABELLE:EINZELWERTE]]': holdings,
  '[[TABELLE:WATCHLIST]]':   watch,
};
for (const [ph, tbl] of Object.entries(blocks)) {
  if (md.includes(ph)) md = md.split(ph).join('\n\n' + tbl + '\n\n');
  else md += '\n\n' + tbl + '\n';
}

return [{ json: { markdown: md } }];
